package com.hmdp.ai.infrastructure.external;

import com.fasterxml.jackson.databind.JsonNode;import com.fasterxml.jackson.databind.ObjectMapper;import com.hmdp.ai.domain.artifact.Citation;import com.hmdp.ai.domain.external.*;import com.hmdp.ai.domain.run.UsageSummary;import com.hmdp.ai.domain.tool.*;import com.hmdp.ai.shared.id.AiIdGenerator;import org.springframework.stereotype.Component;import java.util.*;
@Component public class ExternalSearchToolProtocolAdapter implements ToolProtocolAdapter {private final ExternalSearchGateway gateway;private final ObjectMapper mapper;private final AiIdGenerator ids;public ExternalSearchToolProtocolAdapter(ExternalSearchGateway gateway,ObjectMapper mapper,AiIdGenerator ids){this.gateway=gateway;this.mapper=mapper;this.ids=ids;}public ToolProtocol protocol(){return ToolProtocol.EXTERNAL_SEARCH;}public ToolResult execute(ToolDefinition d,ToolInvocation i,JsonNode c){long started=System.currentTimeMillis();try{String query=i.getInput().path("query").asText();if(query.trim().isEmpty())return ToolResult.failure(ToolCallStatus.FAILED,"SEARCH_QUERY_REQUIRED","search query is required",false);List<SearchResult>results=gateway.search(query,Math.max(1,Math.min(20,i.getInput().path("limit").asInt(5))),c);List<Citation>citations=new ArrayList<>();for(SearchResult r:results)citations.add(new Citation(ids.nextId(),null,null,0,null,r.getTitle(),r.getUrl(),null,null,null,null,1.0,r.getSnippet()));return ToolResult.success(mapper.valueToTree(results),citations,Collections.emptyList(),Collections.emptyList(),UsageSummary.empty(System.currentTimeMillis()-started));}catch(Exception e){String code=code(e);return ToolResult.failure(ToolCallStatus.FAILED,code,"external search failed",!code.equals("PROVIDER_NOT_CONFIGURED"));}}private String code(Exception e){Throwable c=e;while(c!=null){if(c.getMessage()!=null&&c.getMessage().matches("[A-Z0-9_]+"))return c.getMessage();c=c.getCause();}return "EXTERNAL_SEARCH_FAILED";}}
